OR_KEYWORD = 'color';\nconst FILL_KEYWORD = 'fill';\nconst BG_FILL = 'bgFill';\nconst STYLECLASS_SEP = ',';\nlet classes = new Map<string, ClassDef>();\nlet diagramId = '';\n\nconst sanitizeText = (txt: string) => common.sanitizeText(txt, getConfig());\n\n/**\n * Called when the parser comes across a (style) class definition\n * @example classDef my-style fill:#f96;\n *\n * @param id - the id of this (style) class\n * @param styleAttributes - the string with 1 or more style attributes (each separated by a comma)\n */\nexport const addStyleClass = function (id: string, styleAttributes = '') {\n  // create a new style class object with this id\n  let foundClass = classes.get(id);\n  if (!foundClass) {\n    foundClass = { id: id, styles: [], textStyles: [] };\n    classes.set(id, foundClass); // This is a classDef\n  }\n  if (styleAttributes !== undefined && styleAttributes !== null) {\n    styleAttributes.split(STYLECLASS_SEP).forEach((attrib) => {\n      // remove any trailing ;\n      const fixedAttrib = attrib.replace(/([^;]*);/, '$1').trim();\n\n      // replace some style keywords\n      if (RegExp(COLOR_KEYWORD).exec(attrib)) {\n        const newStyle1 = fixedAttrib.replace(FILL_KEYWORD, BG_FILL);\n        const newStyle2 = newStyle1.replace(COLOR_KEYWORD, FILL_KEYWORD);\n        foundClass.textStyles.push(newStyle2);\n      }\n      foundClass.styles.push(fixedAttrib);\n    });\n  }\n};\n\n/**\n * Called when the parser comes across a style definition\n * @example style my-block-id fill:#f96;\n *\n * @param id - the id of the block to style\n * @param styles - the string with 1 or more style attributes (each separated by a comma)\n */\nexport const addStyle2Node = function (id: string, styles = '') {\n  const foundBlock = blockDatabase.get(id)!;\n  if (styles !== undefined && styles !== null) {\n    foundBlock.styles = styles.split(STYLECLASS_SEP);\n  }\n};\n\n/**\n * Add a CSS/style class to the block with the given id.\n * If the block isn't already in the list of known blocks, add it.\n * Might be called by parser when a CSS/style class should be applied to a block\n *\n * @param itemIds - The id or a list of ids of the item(s) to apply the css class to\n * @param cssClassName - CSS class name\n */\nexport const setCssClass = function (itemIds: string, cssClassName: string) {\n  itemIds.split(',').forEach(function (id: string) {\n    let foundBlock = blockDatabase.get(id);\n    if (foundBlock === undefined) {\n      const trimmedId = id.trim();\n      foundBlock = { id: trimmedId, type: 'na', children: [] } as Block;\n      blockDatabase.set(trimmedId, foundBlock);\n    }\n    if (!foundBlock.classes) {\n      foundBlock.classes = [];\n    }\n    foundBlock.classes.push(cssClassName);\n  });\n};\n\n/**\n * Next palette slot to hand out.\n *\n * Composites only, and one counter across the whole parse -- exactly what the flowchart\n * does for its subgraphs. There, `declarationIndex` is built by walking `subGraphs` and\n * nothing else, and every palette selector it emits is a `.cluster` or a collapsed\n * subgraph; a plain node never takes a slot. A block diagram's containers are its\n * composites, so those are what take one here.\n *\n * A nested composite continues the cycle rather than restarting it, which is what keeps\n * two sibling containers from opening on the same colour.\n */\nlet nextColorIndex = 0;\n\nconst populateBlockDatabase = (_blockList: Block[], parent: Block): void => {\n  const blockList = _blockList.flat();\n  const children = [];\n  const columnSettingBlock = blockList.find((b) => b?.type === 'column-setting');\n  const column = columnSettingBlock?.columns ?? -1;\n  for (const block of blockList) {\n    if (\n      typeof column === 'number' &&\n      column > 0 &&\n      block.type !== 'column-setting' &&\n      typeof block.widthInColumns === 'number' &&\n      block.widthInColumns > column\n    ) {\n      log.warn(\n        `Block ${block.id} width ${block.widthInColumns} exceeds configured column width ${column}`\n      );\n    }\n    if (block.label) {\n      block.label = sanitizeText(block.label);\n    }\n    if (block.type === 'classDef') {\n      addStyleClass(block.id, block.css);\n      continue;\n    }\n    if (block.type === 'applyClass') {\n      setCssClass(block.id, block?.styleClass ?? '');\n      continue;\n    }\n    if (block.type === 'applyStyles') {\n      if (block?.stylesStr) {\n        addStyle2Node(block.id, block?.stylesStr);\n      }\n      continue;\n    }\n    if (block.type === 'column-setting') {\n      parent.columns = block.columns ?? -1;\n    } else if (block.type === 'edge') {\n      const count = (edgeCount.get(block.id) ?? 0) + 1;\n      edgeCount.set(block.id, count);\n      block.id = count + '-' + block.id;\n      edgeList.push(block);\n    } else {\n      if (!block.label) {\n        if (block.type === 'composite') {\n          block.label = '';\n          // log.debug('abc89 composite', block);\n        } else {\n          block.label = block.id;\n        }\n      }\n      const existingBlock = blockDatabase.get(block.id);\n\n      if (existingBlock === undefined) {\n        // Assigned here, before the recursion into `block.children` below, so an outer\n        // composite takes a lower slot than any composite nested inside it.\n        if (block.type === 'composite') {\n          block.colorIndex = nextColorIndex++;\n        }\n        blockDatabase.set(block.id, block);\n      } else {\n        // Add newer relevant data to aggregated node\n        if (block.type !== 'na') {\n          existingBlock.type = block.type;\n        }\n        if (block.label !== block.id) {\n          existingBlock.label = block.label;\n        }\n      }\n\n      if (block.children) {\n        populateBlockDatabase(block.children, block);\n      }\n      if (block.type === 'space') {\n        // log.debug('abc95 space', block);\n        const w = block.width ?? 1;\n        for (let j = 0; j < w; j++) {\n          const newBlock = clone(block);\n          newBlock.id = newBlock.id + '-' + j;\n          blockDatabase.set(newBlock.id, newBlock);\n          children.push(newBlock);\n        }\n      } else if (existingBlock === undefined) {\n        children.push(block);\n      }\n    }\n  }\n  parent.children = children;\n};\n\nlet blocks: Block[] = [];\nlet rootBlock = { id: 'root', type: 'composite', children: [], columns: -1 } as Block;\n\nconst clear = (): void => {\n  log.debug('Clear called');\n  commonClear();\n  rootBlock = { id: 'root', type: 'composite', children: [], columns: -1 } as Block;\n  blockDatabase = new Map([['root', rootBlock]]);\n  blocks = [];\n  classes = new Map();\n\n  edgeList = [];\n  edgeCount = new Map();\n  diagramId = '';\n  nextColorIndex = 0;\n};\n\nexport function typeStr2Type(typeStr: string) {\n  log.debug('typeStr2Type', typeStr);\n  switch (typeStr) {\n    case '[]':\n      return 'square';\n    case '()':\n      log.debug('we have a round');\n      return 'round';\n    case '(())':\n      return 'circle';\n    case '>]':\n      return 'rect_left_inv_arrow';\n    case '{}':\n      return 'diamond';\n    case '{{}}':\n      return 'hexagon';\n    case '([])':\n      return 'stadium';\n    case '[[]]':\n      return 'subroutine';\n    case '[()]':\n      return 'cylinder';\n    case '((()))':\n      return 'doublecircle';\n    case '[//]':\n      return 'lean_right';\n    case '[\\\\\\\\]':\n      return 'lean_left';\n    case '[/\\\\]':\n      return 'trapezoid';\n    case '[\\\\/]':\n      return 'inv_trapezoid';\n    case '<[]>':\n      return 'block_arrow';\n    default:\n      return 'na';\n  }\n}\n\nexport function edgeTypeStr2Type(typeStr: string): string {\n  log.debug('typeStr2Type', typeStr);\n  switch (typeStr) {\n    case '==':\n      return 'thick';\n    default:\n      return 'normal';\n  }\n}\n\nexport function edgeStrToEdgeData(typeStr: string): string {\n  const lastChar = typeStr.trim().slice(-1);\n  switch (lastChar) {\n    case 'x':\n      return 'arrow_cross';\n    case 'o':\n      return 'arrow_circle';\n    case '>':\n      return 'arrow_point';\n    default:\n      return '';\n  }\n}\n\nexport function edgeStrToEdgeStartData(typeStr: string): string {\n  const firstChar = typeStr.trim().charAt(0);\n  switch (firstChar) {\n    case 'x':\n      return 'arrow_cross';\n    case 'o':\n      return 'arrow_circle';\n    case '<':\n      return 'arrow_point';\n    default:\n      return 'arrow_open';\n  }\n}\n\nexport function edgeStrToThickness(typeStr: string): string {\n  return typeStr.includes('==') ? 'thick' : 'normal';\n}\n\nexport function edgeStrToPattern(typeStr: string): string {\n  if (typeStr.includes('.-')) {\n    return 'dotted';\n  }\n  return 'solid';\n}\n\nlet cnt = 0;\nexport const generateId = () => {\n  cnt++;\n  return 'id-' + Math.random().toString(36).substr(2, 12) + '-' + cnt;\n};\n\nconst setHierarchy = (block: Block[]): void => {\n  rootBlock.children = block;\n  populateBlockDatabase(block, rootBlock);\n  blocks = rootBlock.children;\n};\n\nconst getColumns = (blockId: string): number => {\n  const block = blockDatabase.get(blockId);\n  if (!block) {\n    return -1;\n  }\n  if (block.columns) {\n    return block.columns;\n  }\n  if (!block.children) {\n    return -1;\n  }\n  return block.children.length;\n};\n\n/**\n * Returns all the blocks as a flat array\n * @returns\n */\nconst getBlocksFlat = () => {\n  return [...blockDatabase.values()];\n};\n/**\n * Returns the hierarchy of blocks\n * @returns\n */\nconst getBlocks = () => {\n  return blocks || [];\n};\n\nconst getEdges = () => {\n  return edgeList;\n};\nconst getBlock = (id: string) => {\n  return blockDatabase.get(id);\n};\n\nconst setBlock = (block: Block) => {\n  blockDatabase.set(block.id, block);\n};\n\nconst setDiagramId = (id: string) => {\n  diagramId = id;\n};\n\nconst getDiagramId = () => diagramId;\n\nconst getLogger = () => log;\n\n/**\n * Return all of the style classes\n */\nexport const getClasses = function () {\n  return classes;\n};\n\nconst db = {\n  getConfig: () => configApi.getConfig().block,\n  typeStr2Type: typeStr2Type,\n  edgeTypeStr2Type: edgeTypeStr2Type,\n  edgeStrToEdgeData,\n  edgeStrToEdgeStartData,\n  edgeStrToThickness,\n  edgeStrToPattern,\n  getLogger,\n  getBlocksFlat,\n  getBlocks,\n  getEdges,\n  setHierarchy,\n  getBlock,\n  setBlock,\n  getColumns,\n  getClasses,\n  clear,\n  generateId,\n  setDiagramId,\n  getDiagramId,\n} as const;\n\nexport type BlockDB = typeof db & DiagramDB;\nexport default db;\n", "import * as khroma from 'khroma';\nimport { getIconStyles } from '../globalStyles.js';\nimport { colorSlotCount, hasPalette, isColorTheme, safeLook } from '../common/colorThemeGate.js';\n\n/** Returns the styles given options */\nexport interface BlockChartStyleOptions {\n  arrowheadColor: string;\n  border2: string;\n  clusterBkg: string;\n  clusterBorder: string;\n  edgeLabelBackground: string;\n  fontFamily: string;\n  lineColor: string;\n  mainBkg: string;\n  nodeBorder: string;\n  nodeTextColor: string;\n  strokeWidth?: number;\n  tertiaryColor: string;\n  textColor: string;\n  titleColor: string;\n  /* Supplied by `createUserStyles`, which spreads `config.themeVariables` and adds the\n     theme name and look. Only the colour themes carry the palette arrays. */\n  theme?: string;\n  look?: string;\n  borderColorArray?: string[];\n  bkgColorArray?: string[];\n  THEME_COLOR_LIMIT?: number;\n}\n\n/**\n * Per-composite palette rules, matching what the flowchart does for its subgraphs: one\n * counter over containers, and nothing on the plain shapes.\n *\n * A composite always draws a `rect.composite` inside a `.node` group -- it has no roughjs\n * variant, so unlike the flowchart there is no `.rough-node` prefix to mirror and no\n * hachure path to avoid painting. That one selector is the whole surface.\n *\n * Not `!important`: `composite.ts` puts a block's own `style` declarations in an inline\n * `style` attribute, which has to keep winning over the theme palette.\n */\nconst genColor = (options: BlockChartStyleOptions) => {\n  const { theme, bkgColorArray, borderColorArray } = options;\n  if (!isColorTheme(theme, borderColorArray)) {\n    return '';\n  }\n  const look = safeLook(options.look);\n  const hasBkgColors = hasPalette(bkgColorArray);\n  let sections = '';\n\n  for (let i = 0; i < colorSlotCount(options.THEME_COLOR_LIMIT, borderColorArray); i++) {\n    const borderColor = borderColorArray![i % borderColorArray!.length];\n    const fill = hasBkgColors ? `fill: ${bkgColorArray[i % bkgColorArray.length]};` : '';\n    const slot = `[data-look=\"${look}\"][data-color-id=\"color-${i}\"]`;\n\n    sections += `\n\n    ${slot}.node rect.composite {\n      stroke: ${borderColor};\n      ${fill}\n    }\n`;\n  }\n  return sections;\n};\n\nconst fade = (color: string, opacity: number) => {\n  // @ts-ignore TODO: incorrect types from khroma\n  const channel = khroma.channel;\n\n  const r = channel(color, 'r');\n  const g = channel(color, 'g');\n  const b = channel(color, 'b');\n\n  // @ts-ignore incorrect types from khroma\n  return khroma.rgba(r, g, b, opacity);\n};\n\nconst getStyles = (options: BlockChartStyleOptions) =>\n  `${genColor(options)}\n  .label {\n    font-family: ${options.fontFamily};\n    color: ${options.nodeTextColor || options.textColor};\n  }\n  .cluster-label text {\n    fill: ${options.titleColor};\n  }\n  .cluster-label span {\n    color: ${options.titleColor};\n  }\n\n\n\n  .label text,span {\n    fill: ${options.nodeTextColor || options.textColor};\n    color: ${options.nodeTextColor || options.textColor};\n  }\n\n  .node rect,\n  .node circle,\n  .node ellipse,\n  .node polygon,\n  .node path {\n    fill: ${options.mainBkg};\n    stroke: ${options.nodeBorder};\n    /* From the theme, as every other diagram does. Pinned at 1px here, so block drew a\n       thinner border than an identical flowchart node under any theme asking for more --\n       the neo theme asks for 2.